  ('정민영', 505, 66, 114, '{"poke": 10, "superb": 0, "hyper": 0, "master": 0, "potion": 0, "revive": 0, "stone": 0, "snack": 0, "snack2": 0, "snack3": 1, "snack4": 0, "spray": 2}', '{"starter": 909, "battlePid": 911, "battleShiny": false, "wins": {"909": 0, "910": 0, "911": 313}, "evoCount": 2, "dexRewards": [15, 30, 45, 60, 75, 90, 105, 120, 135, 150]}'),
  ('이소미', 725, 6, 121, '{"poke": 9, "superb": 0, "hyper": 0, "master": 0, "potion": 0, "revive": 0, "stone": 0, "snack": 0, "snack2": 0, "snack3": 1, "snack4": 0, "spray": 2}', '{"starter": 906, "battlePid": 908, "battleShiny": false, "wins": {"906": 0, "907": 0, "908": 315}, "evoCount": 2, "dexRewards": [15, 30, 45, 60, 75, 90, 105, 120, 135, 150]}')
) v(nick, points, xp, level, inventory, gs)
where s.nickname = v.nick and s.class_id = (select id from public.classes where class_code = '0213');

