  ('930380', '정민지', 92, '박준혁', 1006, '2026-09-14T12:43:00+09:00'),
  ('649394', '이소미', 935, '정민영', 961, '2026-09-15T12:42:00+09:00'),
  ('327277', '박준혁', 912, '정민영', 241, '2026-09-17T12:21:00+09:00'),
  ('870193', '정민지', 950, '이소미', 928, '2026-09-29T12:41:00+09:00'),
